INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A1','{"k":"A1","g":"A. Work that isn''t utility work","order":1,"t":"Permits: move agency permits off the contractor","where":[["Project manual 11/3/26","Standard Terms s.7, PDF p.6"],["Plans 11/3/26","Sheet C-1, General Note 11 (and Note 9)"]],"who":"Owner / attorney (project manual); Pinnacle (plan sheet)","cur":["s.7: \"Contractor shall obtain and pay for all permits, approvals, clearances and licenses required to perform the Work.\"","C-1 Note 11: \"THE CONTRACTOR SHALL, AT ITS OWN EXPENSE, OBTAIN ALL NECESSARY PERMITS AND LICENSES TO COMPLETE THE PROJECT. OBTAINING PERMITS, OR DELAYS, IS NOT CAUSE FOR DELAY OF THE CONTRACT OR SCHEDULE.\""],"new":["s.7: \"Contractor shall obtain and pay for the Village of Pleasant Prairie right-of-way / excavation permit(s), any permits required by Contractor''s means and methods, and all Diggers Hotline notifications. Owner, through its Engineer, will obtain the WDNR water main extension approval, WPDES construction site stormwater coverage (NOI), the Village erosion control permit, and the WisDOT permit if one is required. Contractor shall comply with the conditions of all permits.\"","C-1 Note 11: same split, in the sheet''s wording. Note 9: change \"ALL APPLICABLE PERMITS HAVE BEEN OBTAINED\" to \"ALL CONTRACTOR PERMITS HAVE BEEN OBTAINED\"."],"why":"A utility contractor prices unknown agency approvals and schedule risk he can''t control. Pinnacle is already filing the DNR extension.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in; Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A2','{"k":"A2","g":"A. Work that isn''t utility work","order":2,"t":"SWPPP inspections: Pinnacle prices it once, everyone carries the same number","where":[["Plans 11/3/26","Sheet C-6, SWPPP s.5.0 Inspection; General Information"]],"who":"Pinnacle (proposal + plan sheet C-6); Owner (bid form)","cur":["\"INSPECTIONS SHALL BE UNDERTAKEN BY QUALIFIED PERSONNEL PROVIDED BY THE CONTRACTOR ... A STORMWATER POLLUTION PREVENTION PLAN INSPECTION REPORT SHALL BE COMPLETED AND ADDED TO THE SWPPP. RAINFALL SHALL BE RECORDED ON THE SWPPP RAINFALL LOG.\"","\"KEEPING PLANS CURRENT: THE CONTRACTOR SHALL AMEND THE PLAN WHENEVER THERE IS A CHANGE ...\"","\"CONTRACTOR SHALL SUBMIT A COMPLETED NOTICE OF TERMINATION TO OWNER FOR EXECUTION PRIOR TO THEIR FINAL PAY APPLICATION REQUEST.\""],"new":["Pinnacle gives a fixed-fee proposal for SWPPP inspections (every 7 days and within 24 hours of a 1/2\" rain), inspection reports, rainfall log, SWPPP amendments, and the Notice of Termination.","Recommended: Zilber contracts Pinnacle directly (add it to Pinnacle''s CM estimate under condition 6d). Bid form note: \"SWPPP INSPECTION AND REPORTING BY OWNER''S ENGINEER UNDER SEPARATE CONTRACT. CONTRACTOR SHALL MAINTAIN AND REPAIR ALL EROSION CONTROL MEASURES WITHIN 24 HOURS OF NOTICE.\"","Alternative: carry it in the bid as a fixed allowance line, e.g. \"SWPPP inspections by Pinnacle Engineering per proposal dated __/__/__: $______ (all bidders carry this amount)\". Contractor pays Pinnacle.","Sheet C-6 s.5.0: \"INSPECTIONS SHALL BE UNDERTAKEN BY QUALIFIED PERSONNEL PROVIDED BY THE OWNER''S ENGINEER.\" Amend-the-plan and Notice of Termination move to the Engineer."],"why":"Pinnacle gets the work and every bidder carries the same SWPPP cost. Contracting Pinnacle directly avoids a contractor markup on it and keeps the inspector working for you, not the contractor. Either way the Village counts it: condition 7 sizes the security on public improvements plus inspections and construction services.","deliver":"Claude drafts the request to Andy for the SWPPP proposal, the bid form note, and the C-6 markup"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A3','{"k":"A3","g":"A. Work that isn''t utility work","order":3,"t":"Record drawings: contractor gives redlines, Pinnacle draws","where":[["Plans 11/3/26","Sheet C-1, Required Submittals for Records, item 3"]],"who":"Pinnacle (plan sheet)","cur":["\"3. UNDERGROUND UTILITY LOCATION RECORD DRAWINGS\""],"new":["\"3. FIELD RECORD MARKUPS (REDLINES) OF INSTALLED WATER MAIN, VALVES, HYDRANTS AND FITTINGS WITH TIES TO SURFACE FEATURES. RECORD DRAWINGS WILL BE PREPARED BY THE ENGINEER.\""],"why":"Approval letter condition 6d already puts as-builts and record drawings in Pinnacle''s CM estimate. As written we''d pay for them twice.","deliver":"Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A4','{"k":"A4","g":"A. Work that isn''t utility work","order":4,"t":"Geotech: hand it out, drop the ''more borings at your cost'' line","where":[["Plans 11/3/26","Sheet C-1, General Note 2"]],"who":"Pinnacle (plan sheet)","cur":["\"THE CONTRACTOR IS RESPONSIBLE FOR PERFORMING ANY ADDITIONAL SOILS INVESTIGATIONS THEY FEEL IS NECESSARY ... AT NO ADDITIONAL COST TO THE OWNER.\""],"new":["Delete that sentence. Include the geotechnical report in the bid package (Pinnacle to confirm which report covers the watermain route)."],"why":"Bidders price their own borings or a soils contingency. Giving them the report is cheaper.","deliver":"Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A5','{"k":"A5","g":"A. Work that isn''t utility work","order":5,"t":"Pricing: state lump sum on the proposal form","where":[["Project manual 11/3/26","Proposal form, PDF p.12 (header)"]],"who":"Pinnacle (proposal form)","cur":["Proposal form has engineer''s quantities, contractor quantities and unit prices, but never says whether the bid is lump sum or unit price. Art. II says \"lump sum ... or the amount of the general proposal\"; s.10(a) pays \"at applicable unit prices or percentage of total completion\"."],"new":["Add one header line to the proposal form: \"LUMP SUM BID. UNIT PRICES ARE USED ONLY TO PRICE OWNER-DIRECTED CHANGES.\" No change to Art. II, s.10(a) or Sheet C-1 Note 5."],"why":"Closes the gap that would let a contractor bill quantity overruns at unit prices, and gives the Village one fixed contract number for the 120% security.","deliver":"Claude gives Pinnacle the one-line header text"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A6','{"k":"A6","g":"A. Work that isn''t utility work","order":6,"t":"Existing utilities: add a potholing line item","where":[["Project manual 11/3/26","Proposal form, PDF p.12 (new item)"],["Project manual 11/3/26","Standard Terms s.21, PDF p.9"]],"who":"Pinnacle (plan sheet); Owner / attorney (project manual)","cur":["s.21: \"No representations are made by the Owner ... as to the existence or nature of visible or invisible surface or subsurface difficulties ... whether shown on the plans or not ...\"","Proposal form: no potholing item."],"new":["Add: \"Potholing / exploratory excavation at existing utility crossings, EA, qty by Engineer.\" (Pinnacle sets the count from sheets C-3 and C-4.)"],"why":"Gives the contractor a paid way to find crossings instead of carrying a contingency.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A7','{"k":"A7","g":"A. Work that isn''t utility work","order":7,"t":"STH 31: traffic control and WisDOT","where":[["Project manual 11/3/26","Proposal form, PDF p.12"]],"who":"Pinnacle (plan sheet)","cur":["No traffic control item. Sheet C-1 lists WisDOT contacts."],"new":["Pinnacle confirms whether any work is in the STH 31 right-of-way. If yes, add \"Traffic control, LS\" and Engineer obtains the WisDOT permit (see A1). If no, add a note: \"NO WORK IN STH 31 RIGHT-OF-WAY.\""],"why":"KWU''s letter says the main is in easement outside the right-of-way; the plans should say so plainly.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A8','{"k":"A8","g":"A. Work that isn''t utility work","order":8,"t":"Water shutdowns: who notifies businesses","where":[["Plans 11/3/26","Sheet C-1, General Note 16"]],"who":"Pinnacle (plan sheet)","cur":["\"ANY WATER SHUTDOWNS NEEDED DURING CONSTRUCTION WILL NEED TO BE PERFORMED BY THE VILLAGE OF PLEASANT PRAIRIE DEPARTMENT OF PUBLIC WORKS AND COORDINATED WITH AREA BUSINESSES.\""],"new":["\"... PERFORMED BY THE VILLAGE DPW. CONTRACTOR SHALL REQUEST SHUTDOWNS FROM THE VILLAGE [__] BUSINESS DAYS IN ADVANCE. THE ENGINEER WILL COORDINATE NOTICE TO AFFECTED BUSINESSES.\" (Pinnacle fills in the Village''s lead time.)"],"why":"Notice to neighboring businesses is coordination, not pipe work.","deliver":"Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A9','{"k":"A9","g":"A. Work that isn''t utility work","order":9,"t":"Spill reporting names a general contractor","where":[["Plans 11/3/26","Sheet C-6, SWPPP s.6"]],"who":"Pinnacle (plan sheet)","cur":["\"... SPILLS OF TOXIC OR HAZARDOUS MATERIALS SHALL BE REPORTED TO THE OWNER AND GENERAL CONTRACTOR.\""],"new":["\"... SHALL BE REPORTED TO THE OWNER AND THE ENGINEER.\""],"why":"There is no GC on this contract.","deliver":"Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','A10','{"k":"A10","g":"A. Work that isn''t utility work","order":10,"t":"Survey monuments go to Pinnacle","where":[["DA (draft)","s.7.2 Survey Monuments"]],"who":"Pinnacle (CM scope)","cur":["\"The Developer, at the Developer''s cost, shall place and install on the Property all survey monuments required ...\""],"new":["Include in Pinnacle''s CM estimate (condition 6d). Not in the contractor''s scope."],"why":"Surveyor''s work.","deliver":"No document change; action item"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B1','{"k":"B1","g":"B. Terms that make bidders add money","order":11,"t":"Late-finish exposure: consequential damages + LDs + fees","where":[["Project manual 11/3/26","Standard Terms s.5 and s.5a, PDF p.5"]],"who":"Owner / attorney (project manual)","cur":["\"Contractor shall be responsible to Owner for any and all direct or indirect damages (including, but not limited to, consequential damages) incurred as the result of Contractor''s failure to complete the Work within the Contract Time. All costs, including attorney''s fees, incurred by Owner in enforcing the Agreement ... shall be borne solely by Contractor.\""],"new":["Delete both sentences. Keep s.5a liquidated damages ($500/day) as the sole remedy for delay. Art. IV already gives the prevailing party its fees."],"why":"Uncapped consequential damages on a pipe job gets priced or gets no bid. LDs already protect the schedule.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B2','{"k":"B2","g":"B. Terms that make bidders add money","order":12,"t":"Termination: add notice and cure","where":[["Project manual 11/3/26","Standard Terms s.19, PDF p.8"]],"who":"Owner / attorney (project manual)","cur":["\"The Owner may, upon written notice, terminate the Agreement, with or without cause, if the Owner determines (in its sole discretion) that the Contractor has not performed ... the Contractor shall not be entitled to receive further payment until the Work is finished.\""],"new":["For cause: written notice and 7 days to cure, then Owner may terminate and complete at Contractor''s cost. For convenience: Owner pays for work performed and demobilization."],"why":"\"Sole discretion, no pay until finished\" reads as risk of not getting paid.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B3','{"k":"B3","g":"B. Terms that make bidders add money","order":13,"t":"Pay monthly, not every 60 days","where":[["Project manual 11/3/26","Standard Terms s.10(a), PDF p.7"]],"who":"Owner / attorney (project manual)","cur":["\"Partial payments ... will be made by the Owner every sixty (60) days ...\""],"new":["\"... will be made by the Owner monthly ...\" (matches s.10(b), which already bases pay apps on month-end work)."],"why":"Carrying 60 days of cost gets priced in.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B4','{"k":"B4","g":"B. Terms that make bidders add money","order":14,"t":"$5M umbrella insurance","where":[["Project manual 11/3/26","Standard Terms s.9, PDF p.6"]],"who":"Owner / attorney (project manual)","cur":["\"(iv) Umbrella/excess liability: (a) Each Occurrence in the amount of Five Million Dollars ($5,000,000); and (b) Aggregate ... Five Million Dollars ($5,000,000).\""],"new":["Match Zilber''s standard for site/utility work (from Lisa''s sample). Keep the Village as additional insured, which is what condition 6c requires."],"why":"Small utility contractors may not carry $5M. Pick the number from our standard, not Pinnacle''s form.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B5','{"k":"B5","g":"B. Terms that make bidders add money","order":15,"t":"Indemnity: limit to contractor''s fault","where":[["Project manual 11/3/26","Standard Terms s.8, PDF p.6"],["Plans 11/3/26","Sheet C-1, General Note 15"]],"who":"Owner / attorney (project manual); Pinnacle (plan sheet)","cur":["C-1 Note 15: \"THE CONTRACTOR SHALL INDEMNIFY THE OWNER, ENGINEER, AND THEIR AGENTS FROM ALL LIABILITY INVOLVED WITH THE CONSTRUCTION, INSTALLATION, AND TESTING OF THE WORK ON THIS PROJECT.\""],"new":["Note 15: \"... TO THE EXTENT CAUSED BY THE NEGLIGENT ACTS OR OMISSIONS OF THE CONTRACTOR, ITS SUBCONTRACTORS, OR ANYONE FOR WHOM IT IS RESPONSIBLE.\" Align s.8 to Zilber''s standard."],"why":"\"All liability\" reads as covering the engineer''s own design errors.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in; Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B6','{"k":"B6","g":"B. Terms that make bidders add money","order":16,"t":"Add a differing site conditions clause","where":[["Project manual 11/3/26","Standard Terms s.21, PDF p.9"]],"who":"Owner / attorney (project manual)","cur":["\"... the Bid Price for the work covered by this Agreement must cover satisfactory completion thereof on this condition.\""],"new":["Add: \"If Contractor encounters subsurface conditions materially different from those shown in the Contract Documents or the geotechnical report, Contractor shall stop affected work and notify Owner in writing; the Contract Sum and Time will be equitably adjusted.\""],"why":"Without it, every bidder carries a subsurface contingency.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','B7','{"k":"B7","g":"B. Terms that make bidders add money","order":17,"t":"Directional drilling sub named in the bid","where":[["Project manual 11/3/26","Proposal form PDF p.12; Standard Terms s.12, PDF p.7"]],"who":"Owner / attorney (project manual)","cur":["s.12: \"Contractor shall not sublet the Work, either in whole or in part, without prior, express and written consent of Owner.\""],"new":["Proposal form: add \"Directional drilling subcontractor: ________\". s.12: \"Subcontractors named in the Contractor''s Proposal are deemed approved.\""],"why":"312 LF of 16\" drill is specialty work most utility contractors sub out.","deliver":"Claude drafts the revised manual text (redline) for Pinnacle to drop in"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','C1','{"k":"C1","g":"C. Missing steps (actions, not edits)","order":18,"t":"Village-prequalified contractors only","where":[["Plans 11/3/26","Sheet C-1, Village Note 3"]],"who":"Jason / Village","cur":["\"ALL WORK WITHIN VILLAGE RIGHTS-OF-WAY, PUBLIC EASEMENTS, OR ON VILLAGE FACILITIES SHALL BE COMPLETED ... BY PREQUALIFIED CONTRACTORS ...\""],"new":["Get the Village''s prequalified list from Kurt and invite only from it."],"why":"A non-prequalified low bidder can''t do the work.","deliver":"No document change; action item"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','C2','{"k":"C2","g":"C. Missing steps (actions, not edits)","order":19,"t":"Expired wetland permits may block all permits","where":[["Approval letter","p.2"]],"who":"Jason / Village","cur":["\"Valid wetland fill permits/approvals are required to be submitted from the WI DNR and ACOE prior to issuance of any permits.\" DNR permit expired 9/26/25; ACOE 12/3/25."],"new":["Ask Kurt/Peggy whether this applies to the watermain permits."],"why":"Could stop the job after the contract is signed.","deliver":"No document change; action item"}',1,1793830989352,'seed');
INSERT OR REPLACE INTO docs(col,id,data,ver,updated_at,updated_by) VALUES('reviewItems','C3','{"k":"C3","g":"C. Missing steps (actions, not edits)","order":20,"t":"Floodplain and wetland near the drill","where":[["Plans 11/3/26","Sheet C-4"]],"who":"Pinnacle","cur":["Sheet shows FLOODPLAIN POST-PROJECT EL. 713.3 and the wetland preservation easement next to the 312 LF drill."],"new":["Pinnacle confirms bore pits, spoil and staging are outside the wetland and floodplain, and shows it on the plan."],"why":"Avoids a surprise permit.","deliver":"Claude marks up the sheet (clouded PDF) for Pinnacle to revise in CAD"}',1,1793830989352,'seed');
